import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './tests/memi',
  fullyParallel: false,
  retries: 0,
  reporter: 'list',
  use: {
    ...devices['Desktop Chrome'],
    baseURL: 'http://127.0.0.1:43173',
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
  },
  webServer: {
    command: 'npm run dev -- --host 127.0.0.1 --port 43173',
    url: 'http://127.0.0.1:43173',
    reuseExistingServer: false,
    timeout: 120_000,
  },
});

import { expect, test } from '@playwright/test';

test('recruiter command menu supports the complete keyboard journey', async ({ page }) => {
  await page.goto('/');
  await page.getByRole('button', { name: 'Recruiter' }).click();

  const trigger = page.getByTestId('command-menu-trigger');
  await expect(trigger).toBeVisible();
  await expect(trigger).toHaveAccessibleName('Open command menu');

  await page.keyboard.press('ControlOrMeta+K');
  const dialog = page.getByRole('dialog', { name: 'Navigate Paraform' });
  await expect(dialog).toBeVisible();
  const search = dialog.getByRole('combobox', { name: 'Search destinations' });
  await expect(search).toBeFocused();
  await search.fill('Candidates');
  await page.keyboard.press('Enter');
  await expect(dialog).toBeHidden();
  await expect(page.getByRole('heading', { name: 'Candidates' })).toBeVisible();

  await trigger.click();
  await expect(dialog).toBeVisible();
  await page.keyboard.press('Escape');
  await expect(dialog).toBeHidden();
  await expect(trigger).toBeFocused();

  await page.getByRole('textbox', { name: 'Search candidates' }).focus();
  await page.keyboard.press('ControlOrMeta+K');
  await expect(dialog).toBeHidden();
});

test('command menu remains functional with reduced motion', async ({ page }) => {
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await page.goto('/');
  await page.getByRole('button', { name: 'Recruiter' }).click();
  await page.getByTestId('command-menu-trigger').click();
  await expect(page.getByRole('dialog', { name: 'Navigate Paraform' })).toBeVisible();
});
